def conjugate(verb):
    if not isinstance(verb, str):
        raise ValueError("The input verb must be a string.")
    if not verb.endswith(('ar', 'er', 'ir')):
        raise ValueError("The input verb must end with 'ar', 'er', or 'ir'.")

    suffixes = {
        'ar': ['o', 'as', 'a', 'amos', 'ais', 'an'],
        'er': ['o', 'es', 'e', 'emos', 'eis', 'en'],
        'ir': ['o', 'es', 'e', 'imos', 'is', 'en']
    }

    stem = verb[:-2]
    conjugations = [stem + suffix for suffix in suffixes[verb[-2:]]]

    return {verb: conjugations}
